func runSemanticStale(ctx context.Context, cmd *cobra.Command, opts Options, target string, jsonOut bool) error {
	report, err := semanticStaleReport(ctx, opts, target)
	if err != nil {
		return err
	}
	if jsonOut {
		data, err := json.MarshalIndent(report, "", "  ")
		if err != nil {
