func validateSeedAgentOutput(out seedAgentOutput, phase string) error {
	if out.SchemaVersion != 1 {
		return fmt.Errorf("agent %s output has unsupported schema_version %d", phase, out.SchemaVersion)
	}
	if out.Status != "success" {
		return fmt.Errorf("agent %s output status %q is not success", phase, out.Status)
	}
	return nil
}

func truncateAgentWarning(warning string) string {
	const maxWarningBytes = 4000
	if len(warning) <= maxWarningBytes {
		return warning
	}
	return warning[:maxWarningBytes] + "\n[truncated]"
}

func promptSeedTimeoutAction(opts seedCommandOptions, timeout time.Duration, fallback string) string {
	if opts.noInteractive || !stdinIsTerminal() {
		return fallback
	}
	fmt.Fprintf(os.Stderr, "Deep synthesis has been running for %s. Keep quick result, continue, or fail?\n[k]eep quick / [c]ontinue / [f]ail: ", timeout)
	var response string
	if _, err := fmt.Fscanln(os.Stdin, &response); err != nil {
		return fallback
	}
	switch strings.ToLower(strings.TrimSpace(response)) {
	case "c", "continue":
		return "continue"
	case "f", "fail":
		return "fail"
	default:
		return "keep-quick"
	}
}

func stdinIsTerminal() bool {
	info, err := os.Stdin.Stat()
	return err == nil && (info.Mode()&os.ModeCharDevice) != 0
}

func seedAgentCommandArgs(repoDir, phase string, opts seedCommandOptions) ([]string, error) {
	switch opts.agent {
	case "command":
		if len(opts.agentCommand) == 0 {
			return nil, errors.New("--agent-command is required when --agent command")
		}
		return append([]string(nil), opts.agentCommand...), nil
	case "codex":
		schemaPath, err := writeSeedAgentOutputSchema()
		if err != nil {
			return nil, err
		}
		return []string{"codex", "exec", "--skip-git-repo-check", "--ephemeral", "--sandbox", "read-only", "--output-schema", schemaPath, seedAgentPrompt(phase)}, nil
	case "claude-code":
		return []string{"claude", "--print", "--no-session-persistence", "--permission-mode", "dontAsk", "--tools", "", "--system-prompt", seedAgentPrompt(phase)}, nil
	default:
		return nil, fmt.Errorf("unsupported --agent %q", opts.agent)
	}
}

func seedAgentOutputSchema() string {
	return `{"type":"object","required":["schema_version","status","model","artifacts","warnings"],"properties":{"schema_version":{"type":"integer"},"status":{"type":"string"},"model":{"type":"string"},"artifacts":{"type":"object","additionalProperties":{"type":"string"}},"warnings":{"type":"array","items":{"type":"string"}}},"additionalProperties":false}`
}

func writeSeedAgentOutputSchema() (string, error) {
	f, err := os.CreateTemp("", "entire-brain-seed-schema-*.json")
	if err != nil {
		return "", fmt.Errorf("create seed agent output schema: %w", err)
	}
	name := f.Name()
	if _, err := f.WriteString(seedAgentOutputSchema()); err != nil {
		_ = f.Close()
		return "", fmt.Errorf("write seed agent output schema: %w", err)
	}
	if err := f.Chmod(0o600); err != nil {
		_ = f.Close()
		return "", fmt.Errorf("chmod seed agent output schema: %w", err)
	}
	if err := f.Close(); err != nil {
		return "", fmt.Errorf("close seed agent output schema: %w", err)
	}
	return name, nil
}

